-- 线性表模块：顺序表中间插删的后缀搬移方向与长度更新。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT '顺序表的插入与删除', '插入从表尾向 i 右移后缀，删除从 i+1 起左移后缀；两者平均和最坏时间均为 O(n)。', course.id,parent.id,'cs408-sequential-list-insert-delete','AISTU',1,'REVIEWED',3,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-sequential-list-insert-delete' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-sequential-list-insert-delete',1,'REVIEWED','顺序表的插入与删除',JSON_OBJECT('summary','插入前检查位置与容量，再从表尾向 i 右移后缀并写入；删除时保存目标，从 i+1 起将后缀左移，最后更新长度。连续存储使中间更新必须搬移元素，平均和最坏时间为 O(n)。','steps',JSON_ARRAY('插入时从尾部向前右移，避免覆盖未搬走的元素','写入新元素后长度加一','删除时从目标后继开始向前左移','删除后长度减一，移动量取决于后缀长度'),'prerequisite',JSON_OBJECT('contentKey','cs408-sequential-list-storage','title','顺序表的存储表示','description','先理解顺序表的连续物理存储。'),'nextStep',JSON_OBJECT('contentKey','cs408-singly-linked-list','title','单链表的结点与表示','description','继续比较离散结点与指针连接的替代布局。')),JSON_OBJECT('id','sequential-list-insert-delete-v1','prompt','在顺序表位置 i 插入时，为什么后缀应从表尾向 i 右移？','options',JSON_ARRAY(JSON_OBJECT('id','AVOID_OVERWRITE','text','避免先覆盖仍需搬移的原元素'),JSON_OBJECT('id','CONTIGUOUS_MEMORY','text','因为从前向后移动可以让地址更连续')),'correctOptionId','AVOID_OVERWRITE','correctExplanation','正确：从后向前复制可保留每个尚未处理的源元素。','incorrectExplanation','不正确：连续存储不是移动方向的理由；从前向后右移会覆盖后续源值。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-sequential-list-insert-delete' AND existing.content_version=1 WHERE point.content_key='cs408-sequential-list-insert-delete' AND existing.id IS NULL;
